"use strict";
// Pytania – tłumaczenie niemieckie (po numerze nr z questions.js). Pola: tekst, wyjasnienie, zrodlo.
PYTANIA_TLUM.de = {
  "P105": {"tekst": "Die Raumstation umkreist die Erde alle 90 Minuten!", "wyjasnienie": "Die Internationale Raumstation fliegt mit etwa 28.000 km/h. Die Astronauten an Bord sehen pro Tag rund 16 Sonnenauf- und -untergänge.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P107": {"tekst": "Marie Skłodowska-Curie gewann Nobelpreise in zwei verschiedenen Fächern!", "wyjasnienie": "1903 bekam sie den Nobelpreis für Physik (zusammen mit Pierre Curie und Henri Becquerel) und 1911 den für Chemie für die Entdeckung von Polonium und Radium. Sie ist die einzige Person, die in zwei verschiedenen Naturwissenschaften einen Nobelpreis gewonnen hat.", "zrodlo": "Prüfe: nobelprize.org (offizielle Website des Nobelpreises)"},
  "P108": {"tekst": "Im Salzbergwerk Wieliczka in Polen wird seit über 700 Jahren Salz abgebaut!", "wyjasnienie": "Das Bergwerk ist seit dem Mittelalter in Betrieb und kam 1978 auf die allererste UNESCO-Welterbeliste. Unter der Erde gibt es Kapellen, Seen und Skulpturen aus Salz.", "zrodlo": "Prüfe: whc.unesco.org (UNESCO)"},
  "P109": {"tekst": "Das erste Foto eines Schwarzen Lochs wurde 2019 veröffentlicht!", "wyjasnienie": "Das internationale Team des Event Horizon Telescope zeigte ein Bild vom Schatten eines Schwarzen Lochs in der Galaxie M87. Die Daten stammten aus einem weltweiten Netz von Radioteleskopen.", "zrodlo": "Prüfe: eventhorizontelescope.org (Event Horizon Telescope)"},
  "P112": {"tekst": "Bienen teilen mit einem Tanz mit, wo es Futter gibt.", "wyjasnienie": "Honigbienen nutzen einen besonderen Tanz, um anderen Mitgliedern des Volkes zu zeigen, wo Futterquellen liegen. Die Richtung des Tanzes zeigt die Richtung im Verhältnis zur Sonne, und seine Dauer hilft, die Entfernung zum Futter anzugeben.", "zrodlo": "Prüfe: nobelprize.org (offizielle Website des Nobelpreises)"},
  "P122": {"tekst": "Schall breitet sich im Vakuum des Weltalls nicht so aus wie in der Luft!", "wyjasnienie": "Schall ist eine mechanische Welle und braucht ein Medium wie Luft, Wasser oder einen Festkörper. Im Vakuum des Weltalls gibt es nicht genug Materie, damit sich Schall auf normale Weise ausbreitet.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P124": {"tekst": "Die Kontinente bewegen sich jedes Jahr!", "wyjasnienie": "Die tektonischen Platten, auf denen die Kontinente liegen, bewegen sich meist ein paar Zentimeter pro Jahr. Diese Bewegung ist unter anderem für die Entstehung von Gebirgen und für Erdbeben verantwortlich.", "zrodlo": "Prüfe: usgs.gov (USGS – Geologischer Dienst der USA)"},
  "P125": {"tekst": "Nicht alle Sterne sind weiß – ihre Farbe hängt unter anderem von der Temperatur ab!", "wyjasnienie": "Heißere Sterne wirken oft bläulich oder weiß, kühlere orange oder rot. Die Farbe eines Sterns verrät Forschenden etwas über seine Oberflächentemperatur.", "zrodlo": "Prüfe: esa.int (ESA – Europäische Weltraumorganisation)"},
  "P144": {"tekst": "Große Hunde altern schneller als kleine!", "wyjasnienie": "Das stimmt. Forschende verglichen Veränderungen im Körper von Hunden verschiedener Rassen und fanden heraus, dass große Hunde auf Zellebene schneller altern. Das könnte erklären, warum sie meist kürzer leben. Die Studie erschien in der Zeitschrift „Science“.", "zrodlo": "Prüfe: reuters.com (Reuters – Nachrichtenagentur)"},
  "P147": {"tekst": "Eine weitere Astronautencrew ist zur ISS geflogen!", "wyjasnienie": "Das stimmt. Am 1. Oktober 2026 schickte SpaceX die nächste Langzeitcrew zur Internationalen Raumstation. Die Astronauten untersuchen unter anderem, wie sich das Leben in der Schwerelosigkeit auf die Gesundheit auswirkt.", "zrodlo": "Prüfe: reuters.com (Reuters – Nachrichtenagentur)"},
  "P150": {"tekst": "Flamingos sind rosa, weil sie bestimmte Dinge fressen!", "wyjasnienie": "Flamingoküken sind grauweiß. Die rosa Farbe der Federn stammt aus Farbstoffen (Carotinoiden) in den Algen und Krebstieren, die diese Vögel fressen.", "zrodlo": "Prüfe: nationalgeographic.com (National Geographic)"},
  "P156": {"tekst": "Der Blauwal ist das größte Tier, das je auf der Erde gelebt hat!", "wyjasnienie": "Ein Blauwal kann etwa 30 m lang und über 150 Tonnen schwer werden – mehr als die größten Dinosaurier. Sein Herz wiegt so viel wie ein Kleinwagen.", "zrodlo": "Prüfe: fisheries.noaa.gov (NOAA Fisheries)"},
  "P159": {"tekst": "Die Fußabdrücke der Astronauten sind immer noch auf dem Mond!", "wyjasnienie": "Auf dem Mond gibt es weder Wind noch Regen, die die Spuren verwischen könnten. Die Stiefelabdrücke der Apollo-Missionen können Millionen Jahre überdauern.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P161": {"tekst": "Die tiefste Stelle im Ozean ist fast 11 km tief!", "wyjasnienie": "Das Challengertief im Marianengraben im Pazifik ist etwa 11 km tief. Würde man den Mount Everest dort hineinstellen, läge sein Gipfel immer noch über 2 km unter Wasser.", "zrodlo": "Prüfe: oceanservice.noaa.gov (NOAA – US-Behörde für Ozeane und Atmosphäre)"},
  "P162": {"tekst": "Der Körper eines Erwachsenen besteht zu etwa 60 % aus Wasser!", "wyjasnienie": "Wasser steckt in jeder Zelle. Am meisten enthalten Gehirn, Herz und Lunge. Bei Babys ist der Wasseranteil im Körper sogar noch höher.", "zrodlo": "Prüfe: usgs.gov (USGS – Geologischer Dienst der USA)"},
  "P164": {"tekst": "Fingernägel wachsen schneller als Fußnägel!", "wyjasnienie": "Fingernägel wachsen etwa 3 mm pro Monat, Fußnägel um ein Vielfaches langsamer. Bis ein Fußnagel komplett nachgewachsen ist, kann über ein Jahr vergehen.", "zrodlo": "Prüfe: aad.org (Amerikanische Akademie für Dermatologie)"},
  "P169": {"tekst": "Kolibris können rückwärts fliegen!", "wyjasnienie": "Kolibris schlagen dutzende Male pro Sekunde mit den Flügeln, können in der Luft stehen und rückwärts fliegen – als einzige Vögel.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P170": {"tekst": "Ein männlicher Kaiserpinguin brütet das Ei 2 Monate lang ohne zu fressen!", "wyjasnienie": "Im antarktischen Winter hält das Männchen das Ei auf den Füßen unter einer Hautfalte, während das Weibchen im Meer jagt. Das Männchen kann in dieser Zeit einen großen Teil seines Gewichts verlieren.", "zrodlo": "Prüfe: nationalgeographic.com (National Geographic)"},
  "P171": {"tekst": "Ein Großer Panda frisst bis zu 14 Stunden am Tag Bambus!", "wyjasnienie": "Bambus ist nicht sehr nahrhaft, deshalb muss ein Panda sehr viel davon fressen – über ein Dutzend Kilogramm am Tag.", "zrodlo": "Prüfe: worldwildlife.org (WWF)"},
  "P177": {"tekst": "Der Białowieża-Urwald steht auf der UNESCO-Welterbeliste!", "wyjasnienie": "Er ist einer der letzten Reste des ursprünglichen Tieflandwaldes in Europa. 1979 kam er auf die UNESCO-Liste, später wurde der Eintrag um den belarussischen Teil erweitert.", "zrodlo": "Prüfe: whc.unesco.org (UNESCO)"},
  "P178": {"tekst": "Nikolaus Kopernikus „hielt die Sonne an und bewegte die Erde“!", "wyjasnienie": "In seinem 1543 erschienenen Werk „Über die Umschwünge der himmlischen Kreise“ beschrieb Kopernikus ein Modell, in dem die Erde um die Sonne kreist und nicht umgekehrt.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P180": {"tekst": "Der Pole Ignacy Łukasiewicz baute die Petroleumlampe!", "wyjasnienie": "1853 baute Łukasiewicz in Lemberg eine Petroleumlampe, und 1854 gründete er in Bóbrka eine der ersten Erdölförderstätten der Welt.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P181": {"tekst": "Polnische Mathematiker knackten als Erste die Enigma-Verschlüsselung!", "wyjasnienie": "Marian Rejewski, Jerzy Różycki und Henryk Zygalski knackten in den 1930er-Jahren die Verschlüsselung der deutschen Enigma. Sie gaben ihr Wissen an die Briten weiter, was den Alliierten im Zweiten Weltkrieg half.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P182": {"tekst": "Wisława Szymborska hat den Literaturnobelpreis bekommen!", "wyjasnienie": "Die polnische Dichterin erhielt 1996 den Nobelpreis für Literatur. Ihre Gedichte wurden in viele Sprachen übersetzt.", "zrodlo": "Prüfe: nobelprize.org (offizielle Website des Nobelpreises)"},
  "P183": {"tekst": "Olga Tokarczuk ist Nobelpreisträgerin!", "wyjasnienie": "Die polnische Schriftstellerin erhielt den Literaturnobelpreis für das Jahr 2018, der 2019 bekannt gegeben wurde. Sie ist die fünfte polnische Literaturnobelpreisträgerin.", "zrodlo": "Prüfe: nobelprize.org (offizielle Website des Nobelpreises)"},
  "P184": {"tekst": "Eis schwimmt, weil Wasser sich beim Gefrieren ausdehnt!", "wyjasnienie": "Die meisten Stoffe sind im festen Zustand dichter als im flüssigen. Wasser ist die Ausnahme – Eis ist leichter als Wasser, deshalb frieren Seen von oben zu und Fische überleben den Winter unter dem Eis.", "zrodlo": "Prüfe: usgs.gov (USGS – Geologischer Dienst der USA)"},
  "P185": {"tekst": "Das Licht der Sonne braucht etwa 8 Minuten bis zur Erde!", "wyjasnienie": "Die Sonne ist etwa 150 Mio. km entfernt. Wenn wir sie ansehen (mit passenden Filtern!), sehen wir sie so, wie sie vor etwa 8 Minuten war.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P186": {"tekst": "Wenn du zu den Sternen schaust, siehst du die Vergangenheit!", "wyjasnienie": "Das Licht ferner Sterne ist Jahre, sogar Tausende Jahre zu uns unterwegs. Manche Sterne, die wir sehen, haben sich vielleicht längst verändert oder sind erloschen.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P189": {"tekst": "Der erste künstliche Satellit wurde 1957 gestartet!", "wyjasnienie": "Der sowjetische Sputnik 1 war so groß wie ein Wasserball und umkreiste die Erde, wobei er ein Funksignal sendete. Sein Start begann das Raumfahrtzeitalter.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P194": {"tekst": "Mindestens die Hälfte des Sauerstoffs auf der Erde stammt aus dem Ozean!", "wyjasnienie": "Sauerstoff wird vor allem von Plankton produziert – winzigen Algen und Bakterien, die im Wasser schweben. Man schätzt, dass sie mindestens die Hälfte des Sauerstoffs der Erde erzeugen.", "zrodlo": "Prüfe: oceanservice.noaa.gov (NOAA – US-Behörde für Ozeane und Atmosphäre)"},
  "P198": {"tekst": "Baltischer Bernstein ist versteinertes Harz, Millionen Jahre alt!", "wyjasnienie": "Bernstein entstand aus dem Harz von Nadelbäumen, die vor etwa 40 Mio. Jahren wuchsen. In manchen Stücken sind Insekten und Pflanzenteile erhalten.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P199": {"tekst": "Der Wisent wurde dank Zucht in Polen vor dem Aussterben gerettet!", "wyjasnienie": "In freier Wildbahn starben Wisente Anfang des 20. Jahrhunderts aus. Dank der Zucht von Tieren aus Zoos und ihrer Auswilderung im Białowieża-Urwald lebt der Wisent wieder frei. Er ist das größte Landsäugetier Europas.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F7": {"tekst": "Die Mikrowelle macht Essen radioaktiv!", "wyjasnienie": "Mikrowellen sind elektromagnetische Wellen, die Wassermoleküle in Bewegung versetzen und so das Essen erwärmen. Sie machen nichts radioaktiv, und nach dem Ausschalten verschwinden die Wellen.", "zrodlo": "Prüfe: fda.gov (FDA – US-Behörde für Lebens- und Arzneimittel)"},
  "F21": {"tekst": "Normale Alufolie macht dein Handy zu einem Gratis-Ladegerät!", "wyjasnienie": "Videos mit diesem Trick können gestellt sein oder eine versteckte Stromquelle verschweigen. Alufolie selbst erzeugt keine Energie, um ein Handy zu laden.", "zrodlo": "Prüfe: uokik.gov.pl (UOKiK – polnische Verbraucherschutzbehörde)"},
  "F33": {"tekst": "Iga Świątek empfiehlt eine Investmentplattform – verdiene Tausende!", "wyjasnienie": "Auf Facebook tauchten Anzeigen auf, in denen die Tennisspielerin Iga Świątek angeblich zum Investieren auf einer besonderen Plattform aufrief. Das Bild der bekannten Sportlerin sollte die Leute überzeugen, dass es ein sicherer Weg zum Geldverdienen ist. In Wahrheit wurden die Videos manipuliert, teils mit Deepfake-Technik, und das Ziel war, Geld zu ergaunern.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F34": {"tekst": "Vitamin K für Neugeborene verwandelt ihr Blut in Schlamm und verursacht Leukämie!", "wyjasnienie": "In sozialen Medien kursieren Beiträge, die Vitamin-K-Spritze nach der Geburt schade Babys. Die Autoren machen Eltern Angst, das Vitamin verwandle Blut in „Schlamm“ und löse Leukämie aus. In Wahrheit ist Vitamin K sicher und schützt Neugeborene vor gefährlichen Blutungen.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F40": {"tekst": "Dr. Ewa Dąbrowska: Abnehmen mit einer Diät aus Salz und Zitrone!", "wyjasnienie": "Auf Facebook kursierte ein Video, in dem eine bekannte polnische Ärztin angeblich eine Wunderdiät aus wenigen einfachen Zutaten verrät. Der bekannte Name sollte die Zuschauer dazu bringen, auf einen Link mit dem „ganzen Rezept“ zu klicken. In Wahrheit wurde das Video von einer KI erzeugt – das in die Pfanne gestreute Salz fliegt zurück in die Hand – und Dr. Dąbrowska warnte selbst vor den Betrügern.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F42": {"tekst": "Die perfekte Figur in 27 Tagen – möglich mit diesem Hausmittel!", "wyjasnienie": "Auf Facebook und anderen sozialen Netzwerken stößt man auf falsche Versprechen, die oft mit gestohlenen privaten Daten enden.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F43": {"tekst": "5G und Bluetooth verursachen Krebs, und kaum jemand weiß es", "wyjasnienie": "Ein Konto namens „Schädliche Wellen“ behauptet, Bluetooth- und 5G-Wellen verursachten Krebs. Seine „Erkenntnisse“ stützt ein nicht existierender Strahlenforscher namens Jerzy Weber.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F44": {"tekst": "Schau Videos und bekomm tolle Prämien! Das ist kein Trick, das ist die Macht des Online-Marketings!", "wyjasnienie": "In sozialen Medien kursieren Videos, die behaupten, man bekomme für eine bestimmte Anzahl angesehener Reels eine Geldprämie.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F45": {"tekst": "Eine Smartwatch sendet giftige Strahlung direkt in deine Haut!", "wyjasnienie": "In sozialen Medien erschien ein Video über angebliche Gefahren von Smartwatches. Der Ersteller spricht von giftiger Strahlung aus der Uhr und von Chemikalien in Silikonarmbändern.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F48": {"tekst": "Zecken werden absichtlich aus Hubschraubern abgeworfen, um Menschen zu infizieren!", "wyjasnienie": "Das ist eine Verschwörungstheorie ohne jeden Beweis. Dass Forschende Zecken und die Krankheiten, die sie übertragen, untersuchen, heißt nicht, dass jemand sie absichtlich verbreitet.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F75": {"tekst": "Der Mensch stammt vom Schimpansen ab!", "wyjasnienie": "Das ist eine zu starke Vereinfachung der Evolutionstheorie. Menschen und Schimpansen haben einen gemeinsamen Vorfahren von vor Millionen Jahren – Schimpansen sind unsere „Cousins“, nicht unsere „Vorfahren“.", "zrodlo": "Prüfe: nhm.ac.uk (Naturkundemuseum London)"},
  "F76": {"tekst": "Menschen und Dinosaurier lebten zur gleichen Zeit!", "wyjasnienie": "Filme und Zeichentrickserien zeigen oft Menschen neben Dinosauriern. Die großen Dinosaurier starben vor etwa 66 Mio. Jahren aus, die ersten Menschen tauchten erst vor wenigen Millionen Jahren auf.", "zrodlo": "Prüfe: nhm.ac.uk (Naturkundemuseum London)"},
  "F96": {"tekst": "Aprikosenkerne heilen Krebs – die Ärzte verschweigen es!", "wyjasnienie": "Im Netz werden Aprikosenkerne als natürliches Heilmittel beworben. Es gibt keinen Beweis, dass sie Krebs heilen, und ein Stoff darin kann im Körper ein Gift freisetzen – Cyanid.", "zrodlo": "Prüfe: cancer.gov (Nationales Krebsinstitut der USA)"},
  "F98": {"tekst": "Heute Nacht ist der Mars so groß wie der Vollmond!", "wyjasnienie": "Diese Kettennachricht kursiert seit 2003. Selbst wenn der Mars der Erde am nächsten ist, sieht er aus wie ein heller rötlicher Stern, nicht wie ein zweiter Mond.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "F99": {"tekst": "Die Mondlandung 1969 wurde in einem Studio gedreht!", "wyjasnienie": "Das ist eine der bekanntesten Verschwörungstheorien. Die Apollo-Missionen belegen unter anderem Mondgesteinsproben, auf dem Mond zurückgelassene Spiegel, die bis heute Laser von der Erde reflektieren, und Fotos von Raumsonden.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "F100": {"tekst": "Foto: Ein Hai schwimmt nach einem Hurrikan auf einer überfluteten Autobahn!", "wyjasnienie": "Das ist ein bearbeitetes Foto, das nach fast jedem großen Hurrikan wieder auftaucht. Dasselbe Haibild wurde in verschiedene Hochwasserfotos eingefügt.", "zrodlo": "Prüfe: snopes.com (Snopes – Faktencheck-Portal)"},
  "P102": {"tekst": "Kraken haben drei Herzen!", "wyjasnienie": "Zwei Herzen pumpen Blut zu den Kiemen, das dritte verteilt es im restlichen Körper. Krakenblut ist blau, weil es Sauerstoff mit Kupfer transportiert und nicht mit Eisen wie beim Menschen.", "zrodlo": "Prüfe: nationalgeographic.com (National Geographic)"},
  "P103": {"tekst": "Seeotter halten sich beim Schlafen an den Pfoten!", "wyjasnienie": "Otter schlafen auf dem Wasser und halten sich an den Pfoten, damit die Strömung sie im Schlaf nicht trennt. Mütter wickeln ihre Jungen oft in Seetang oder halten sie auf dem Bauch.", "zrodlo": "Prüfe: montereybayaquarium.org (Monterey Bay Aquarium)"},
  "P111": {"tekst": "Krähen können sich jahrelang an menschliche Gesichter erinnern.", "wyjasnienie": "Studien haben gezeigt, dass Krähen die Gesichter von Menschen, die sie als Bedrohung ansehen, erkennen und sich merken können. Mehr noch: Sie erinnern sich lange an sie und reagieren auch bei späteren Begegnungen auf diese Personen. Das zeigt, wie weit entwickelt die geistigen Fähigkeiten dieser Vögel sind.", "zrodlo": "Prüfe: doi.org (wissenschaftliche Publikation (DOI))"},
  "P115": {"tekst": "Fledermäuse können sehen, obwohl sie oft im Dunkeln jagen!", "wyjasnienie": "Anders als viele glauben, sind Fledermäuse nicht blind. Alle Arten haben funktionierende Augen, auch wenn ihr Sehvermögen je nach Art unterschiedlich ist. Viele Fledermäuse nutzen außerdem Echoortung, die ihnen bei der Orientierung und beim Insektenfang hilft.", "zrodlo": "Prüfe: batcon.org (Bat Conservation International)"},
  "P116": {"tekst": "Ein Jahr auf dem Merkur dauert weniger als drei Erdmonate!", "wyjasnienie": "Merkur umkreist die Sonne in etwa 88 Erdtagen. Das ist das kürzeste Jahr aller Planeten im Sonnensystem.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P120": {"tekst": "Blitze schlagen nicht immer nur von den Wolken in den Boden ein!", "wyjasnienie": "Blitze können zwischen Wolken, innerhalb einer Wolke oder zwischen Wolke und Boden entstehen. Es gibt also verschiedene Arten von Blitzen.", "zrodlo": "Prüfe: noaa.gov (NOAA – US-Behörde für Ozeane und Atmosphäre)"},
  "P121": {"tekst": "Auf der Erde gibt es Lebewesen, die in sehr heißen Quellen leben!", "wyjasnienie": "Manche Mikroorganismen, sogenannte Thermophile, gedeihen bei Temperaturen, die viel höher sind, als die meisten Lebewesen aushalten. Man findet sie zum Beispiel in heißen Quellen.", "zrodlo": "Prüfe: nps.gov (Nationalparkbehörde der USA)"},
  "P135": {"tekst": "Australien hat soziale Medien für unter 16-Jährige verboten!", "wyjasnienie": "Seit dem 10. Dezember 2025 dürfen Menschen unter 16 Jahren in Australien keine Konten auf den größten sozialen Plattformen haben. Das Verbot gilt unter anderem für TikTok, Instagram, Snapchat, Facebook und YouTube. Es ist das erste Gesetz dieser Art weltweit, und den Plattformen drohen bei Verstößen sehr hohe Strafen.", "zrodlo": "Prüfe: android.com.pl (Android.com.pl – polnisches Technikportal)"},
  "P138": {"tekst": "Der zweite Pole der Geschichte ist ins All geflogen – 47 Jahre nach Hermaszewski!", "wyjasnienie": "Bis 2025 war Mirosław Hermaszewski, der 1978 flog, der einzige Pole im All. Im Juni 2025 flog Sławosz Uznański-Wiśniewski mit der Mission Ax-4 zur Internationalen Raumstation. Er wurde der zweite Pole im All und der erste auf der ISS, wo er 13 polnische Experimente durchführte.", "zrodlo": "Prüfe: xyz.pl (XYZ.pl – polnisches Nachrichtenportal)"},
  "P146": {"tekst": "Medizin-Nobelpreis für die Steuerung des Gehirns mit Licht!", "wyjasnienie": "Das stimmt. Der Nobelpreis für Physiologie oder Medizin 2026 wurde für die Optogenetik vergeben. Bei dieser Methode schalten Forschende ausgewählte Nervenzellen mit Licht an und aus, um zu verstehen, wie das Gehirn funktioniert.", "zrodlo": "Prüfe: reuters.com (Reuters – Nachrichtenagentur)"},
  "P148": {"tekst": "Der KI-Boom steigert die Nachfrage nach Maschinen zur Chipherstellung!", "wyjasnienie": "Das stimmt. Die Firma ASML, die Maschinen zur Herstellung der modernsten Prozessoren baut, hob ihre Umsatzprognose an. Grund ist die große Nachfrage nach Chips für künstliche Intelligenz.", "zrodlo": "Prüfe: reuters.com (Reuters – Nachrichtenagentur)"},
  "P149": {"tekst": "Bananen sind leicht radioaktiv!", "wyjasnienie": "Bananen enthalten viel Kalium, und ein winziger Teil davon ist das natürliche radioaktive Isotop Kalium-40. Die Dosis ist aber so gering, dass das Essen einer Banane völlig unbedenklich ist.", "zrodlo": "Prüfe: epa.gov (EPA – US-Umweltschutzbehörde)"},
  "P155": {"tekst": "Delfine geben sich gegenseitig „Namen“!", "wyjasnienie": "Große Tümmler haben typische Pfiffe, die wie ein Name funktionieren. Studien zeigten, dass Delfine reagieren, wenn ihr „Namens“-Pfiff aus einem Lautsprecher abgespielt wird.", "zrodlo": "Prüfe: nationalgeographic.com (National Geographic)"},
  "P158": {"tekst": "Ein Tag auf dem Mars dauert fast so lange wie auf der Erde!", "wyjasnienie": "Der Mars dreht sich in etwa 24 Stunden und 37 Minuten um die eigene Achse. Forschende nennen einen Marstag „Sol“.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P160": {"tekst": "Der Mount Everest wächst immer noch!", "wyjasnienie": "Die Indische Platte drückt weiter gegen die Eurasische Platte, deshalb hebt sich der Himalaya langsam. Der Everest wächst um ein paar Millimeter pro Jahr.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P163": {"tekst": "Ein Neugeborenes hat mehr Knochen als ein Erwachsener!", "wyjasnienie": "Ein Baby kommt mit etwa 300 Knochen und Knorpelteilen zur Welt. Beim Wachsen verwachsen viele davon, und ein Erwachsener hat 206.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P165": {"tekst": "Gähnen ist ansteckend – sogar zwischen Menschen und Hunden!", "wyjasnienie": "Wenn man jemanden gähnen sieht, gähnt man oft selbst. Studien zeigen, dass Hunde sich bei ihren Besitzern mit Gähnen „anstecken“ können.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
  "P166": {"tekst": "Eine Giraffe hat genauso viele Halswirbel wie ein Mensch!", "wyjasnienie": "Trotz ihres sehr langen Halses hat eine Giraffe nur 7 Halswirbel – genauso viele wie der Mensch und die meisten Säugetiere. Jeder Wirbel ist aber sehr lang.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P168": {"tekst": "Katzen können nichts Süßes schmecken!", "wyjasnienie": "Bei Katzen funktioniert das Gen für den Süß-Rezeptor nicht. Katzen sind Raubtiere und brauchen diesen Geschmack in der Natur nicht.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
  "P172": {"tekst": "Elefanten erkennen sich im Spiegel!", "wyjasnienie": "In einer Studie von 2006 berührten Elefanten mit dem Rüssel eine Markierung auf ihrem Kopf, die sie nur im Spiegel sehen konnten. Nur wenige Tiere können ihr Spiegelbild so erkennen.", "zrodlo": "Prüfe: pnas.org (Fachzeitschrift PNAS)"},
  "P173": {"tekst": "Ein Axolotl kann ein verlorenes Bein nachwachsen lassen!", "wyjasnienie": "Dieser mexikanische Lurch kann Gliedmaßen und sogar Teile von Herz und Gehirn neu bilden. Forschende untersuchen ihn, um Regeneration besser zu verstehen.", "zrodlo": "Prüfe: nationalgeographic.com (National Geographic)"},
  "P176": {"tekst": "In Kalifornien wächst eine Kiefer, die über 4.800 Jahre alt ist!", "wyjasnienie": "Eine Langlebige Kiefer namens Methuselah wächst in den White Mountains in Kalifornien. Ihr genauer Standort wird geheim gehalten, um sie vor Touristen zu schützen.", "zrodlo": "Prüfe: nps.gov (Nationalparkbehörde der USA)"},
  "P179": {"tekst": "Die polnische Verfassung vom 3. Mai war die erste moderne Verfassung Europas!", "wyjasnienie": "Die 1791 beschlossene Verfassung vom 3. Mai war die erste geschriebene moderne Verfassung in Europa und die zweite weltweit (nach der amerikanischen).", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P187": {"tekst": "Auf dem Jupiter tobt seit Jahrhunderten ein Sturm, der größer ist als die Erde!", "wyjasnienie": "Der Große Rote Fleck ist ein riesiger Wirbel in der Jupiteratmosphäre, der seit über 150 Jahren, vielleicht länger, beobachtet wird. Die ganze Erde würde hineinpassen.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P188": {"tekst": "Der heißeste Planet ist die Venus, nicht der Merkur!", "wyjasnienie": "Merkur ist näher an der Sonne, aber die Venus hat die höchste Temperatur – etwa 465 °C. Ihre dichte Atmosphäre aus Kohlendioxid hält die Wärme fest wie ein Treibhaus.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P190": {"tekst": "Die erste Website entstand 1991 am CERN!", "wyjasnienie": "Der britische Wissenschaftler Tim Berners-Lee erfand das World Wide Web, als er am CERN bei Genf arbeitete. Die erste Website erklärte, was das WWW ist.", "zrodlo": "Prüfe: home.cern (CERN)"},
  "P192": {"tekst": "Das Wort „Roboter“ haben Tschechen erfunden!", "wyjasnienie": "Das Wort tauchte 1920 in einem Theaterstück von Karel Čapek auf, vorgeschlagen hat es sein Bruder Josef. Es kommt vom tschechischen „robota“, also Arbeit, Frondienst.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P193": {"tekst": "Der QR-Code wurde in Japan für eine Autofabrik erfunden!", "wyjasnienie": "1994 entwickelte die Firma Denso Wave den QR-Code, um Autoteile schneller verfolgen zu können. Heute nutzen wir ihn unter anderem für Zahlungen und Tickets.", "zrodlo": "Prüfe: qrcode.com (Denso Wave – Erfinder des QR-Codes)"},
  "P195": {"tekst": "Die größte Wüste der Welt ist die Antarktis!", "wyjasnienie": "Eine Wüste ist ein Gebiet mit sehr wenig Niederschlag, nicht nur Sand. In der Antarktis fällt sehr wenig Schnee, deshalb ist sie die größte Wüste der Erde.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P197": {"tekst": "Im Toten Meer kann man nicht so leicht ertrinken, weil das Wasser den Körper nach oben drückt!", "wyjasnienie": "Das Tote Meer ist um ein Vielfaches salziger als der Ozean. Das dichte, salzige Wasser lässt einen Menschen an der Oberfläche treiben, ohne zu schwimmen.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P200": {"tekst": "Hühner und andere Vögel sind Nachfahren der Dinosaurier!", "wyjasnienie": "Vögel haben sich aus kleinen Raubdinosauriern entwickelt. Forschende halten sie sogar für lebende Dinosaurier – sie haben unter anderem einen ähnlichen Knochenbau und Federn wie manche von ihnen.", "zrodlo": "Prüfe: nhm.ac.uk (Naturkundemuseum London)"},
  "F2": {"tekst": "Verschluckter Kaugummi bleibt 7 Jahre im Magen!", "wyjasnienie": "Ein bekannter Mythos macht Kindern Angst, Kaugummi „verklebe“ den Magen. Kaugummi wird nicht verdaut, wandert aber durch den Verdauungstrakt und wird nach ein paar Tagen mit allem anderen ausgeschieden.", "zrodlo": "Prüfe: mayoclinic.org (Mayo Clinic)"},
  "F4": {"tekst": "Nach dem Rasieren wachsen Haare dicker und dunkler nach!", "wyjasnienie": "Beiträge über „Schönheitsgeheimnisse“ wiederholen das seit Jahren. Rasieren ändert weder Dicke noch Farbe der Haare, es schneidet nur die dünne Spitze ab, deshalb kann sich frisch nachwachsendes Haar härter anfühlen.", "zrodlo": "Prüfe: aad.org (Amerikanische Akademie für Dermatologie)"},
  "F5": {"tekst": "Mit nassen Haaren in die Kälte zu gehen, verursacht eine Erkältung!", "wyjasnienie": "Eltern und Großeltern wiederholen diese Warnung oft. Erkältungen werden von Viren ausgelöst, nicht von Kälte oder nassen Haaren allein. Kälte kann das Krankwerden höchstens begünstigen, aber ohne Kontakt mit dem Virus erkältet man sich nicht.", "zrodlo": "Prüfe: nhs.uk (NHS – britischer staatlicher Gesundheitsdienst)"},
  "F15": {"tekst": "Der Strauß steckt den Kopf in den Sand, wenn er Angst hat!", "wyjasnienie": "Strauße tun das nicht aus Angst. Wenn sie den Kopf am Nest senken, kann es aus der Ferne so aussehen, als würden sie ihn im Boden vergraben.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F50": {"tekst": "Stiere werden wütend, wenn sie die Farbe Rot sehen!", "wyjasnienie": "Dieser Glaube stammt vom Stierkampf, bei dem der Torero ein rotes Tuch schwenkt. Stiere sehen Rot schlecht – sie reagieren auf die Bewegung des Tuchs, nicht auf seine Farbe.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F52": {"tekst": "Wenn du ein Vogelküken anfasst, verstößt die Mutter es!", "wyjasnienie": "Diesen Mythos erzählen Eltern und Lehrkräfte Kindern. Die meisten Vögel riechen schlecht und verlassen ihre Jungen nicht wegen menschlichen Geruchs. Trotzdem lässt man Küken am besten in Ruhe, außer sie sind in Gefahr.", "zrodlo": "Prüfe: audubon.org (Audubon – Vogelschutzorganisation)"},
  "F54": {"tekst": "Fingerknacken verursacht Arthritis!", "wyjasnienie": "Viele haben diese Warnung als Kind gehört. Das Knacken sind platzende Gasbläschen in der Gelenkflüssigkeit. Studien haben nicht gezeigt, dass Fingerknacken zu Gelenkentzündungen führt.", "zrodlo": "Prüfe: health.harvard.edu (Harvard Health)"},
  "F55": {"tekst": "Lesen bei schwachem Licht schadet den Augen dauerhaft!", "wyjasnienie": "Eltern verbieten oft, mit Taschenlampe unter der Decke zu lesen. Schwaches Licht kann die Augen ermüden und kurz unangenehm sein, schadet dem Sehvermögen aber nicht dauerhaft.", "zrodlo": "Prüfe: aao.org (Amerikanische Akademie für Augenheilkunde)"},
  "F57": {"tekst": "Wikinger trugen Helme mit Hörnern!", "wyjasnienie": "So zeigen sie Filme, Zeichentrickserien und Kostüme. Archäologen haben keine Beweise gefunden, dass Wikinger im Kampf Hörnerhelme trugen. Dieses Bild machten Opernkostüme im 19. Jahrhundert populär.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F60": {"tekst": "Eine Münze, die von einem Wolkenkratzer fällt, kann einen Passanten töten!", "wyjasnienie": "Im Internet heißt es, eine kleine Münze wirke aus großer Höhe wie eine Kugel. Der Luftwiderstand begrenzt ihre Geschwindigkeit – der Treffer kann wehtun, tötet aber nicht.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
  "F65": {"tekst": "Ein halbierter Regenwurm wird zu zwei Regenwürmern!", "wyjasnienie": "Kinder probieren das oft im Garten aus. Manchmal überlebt der Teil mit dem Kopf und bildet einen Teil des Körpers neu, aber aus einem Regenwurm werden keine zwei neuen.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F66": {"tekst": "Nach dem Essen muss man eine Stunde warten, sonst bekommt man im Wasser einen Krampf und ertrinkt!", "wyjasnienie": "Jedes Kind hört diese Warnung am Wasser. Es gibt keine Beweise, dass Baden nach dem Essen das Ertrinkungsrisiko erhöht. Vorsicht am Wasser gilt aber immer – egal, ob man gegessen hat.", "zrodlo": "Prüfe: redcross.org (Rotes Kreuz)"},
  "F67": {"tekst": "Alkohol wärmt den Körper bei Frost!", "wyjasnienie": "Nach Alkohol fühlen wir Wärme, weil sich die Blutgefäße in der Haut weiten. Tatsächlich verliert der Körper dann schneller Wärme, was das Risiko einer Unterkühlung erhöht.", "zrodlo": "Prüfe: nhs.uk (NHS – britischer staatlicher Gesundheitsdienst)"},
  "F77": {"tekst": "Das Blut in den Venen ist blau und wird erst an der Luft rot!", "wyjasnienie": "In Schulbuchgrafiken sind Venen blau, und durch die Haut wirken Venen bläulich. Menschliches Blut ist immer rot – in den Venen nur dunkler als in den Arterien.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F78": {"tekst": "Jeder Mensch verschluckt im Schlaf 8 Spinnen pro Jahr!", "wyjasnienie": "Diese „Fun Fact“ kursiert seit den 1990ern im Internet. Keine Studie bestätigt sie – Spinnen meiden schlafende Menschen, weil Atem und Vibrationen sie abschrecken.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
  "F80": {"tekst": "Jede Biene und Wespe stirbt nach dem Stechen!", "wyjasnienie": "Nur die Honigbiene stirbt, wenn sie ein Säugetier sticht, weil ihr Stachel mit Widerhaken in der Haut stecken bleibt. Wespen, Hornissen und Hummeln können mehrmals stechen.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F81": {"tekst": "Eine Katze landet immer auf den Pfoten, ein Sturz aus dem Fenster kann ihr also nichts anhaben!", "wyjasnienie": "Katzen haben einen Reflex, sich in der Luft zu drehen, aber Stürze von Balkonen und aus Fenstern enden oft mit schweren Verletzungen. Tierärzte sprechen sogar vom „High-Rise-Syndrom“.", "zrodlo": "Prüfe: aspca.org (ASPCA – Tierschutzorganisation)"},
  "F82": {"tekst": "Igeln gibt man am besten Milch!", "wyjasnienie": "In Polen stellen viele Menschen Igeln ein Schälchen Milch hin. Igel vertragen keine Laktose, Milch kann ihnen schaden. Besser sind frisches Wasser und spezielles Futter.", "zrodlo": "Prüfe: britishhedgehogs.org.uk (Britische Gesellschaft zum Schutz der Igel)"},
  "F83": {"tekst": "Brot ist gesundes Futter für Enten!", "wyjasnienie": "Enten mit Brot zu füttern ist ein beliebter Zeitvertreib in Parks. Brot liefert den Vögeln nicht die nötigen Nährstoffe, und Reste verschmutzen das Wasser. Besser sind z. B. Haferflocken oder klein geschnittenes Gemüse.", "zrodlo": "Prüfe: rspb.org.uk (RSPB – britische Vogelschutzgesellschaft)"},
  "P101": {"tekst": "Honig verdirbt nie!", "wyjasnienie": "Honig ist sehr süß, enthält wenig Wasser und ist leicht sauer, deshalb können sich Bakterien darin nicht vermehren. Archäologen fanden in altägyptischen Gräbern Honig, der nach Jahrtausenden noch essbar war.", "zrodlo": "Prüfe: smithsonianmag.com (Smithsonian Magazine)"},
  "P104": {"tekst": "Auf der Venus dauert ein Tag länger als ein Jahr!", "wyjasnienie": "Die Venus dreht sich extrem langsam um ihre Achse, in etwa 243 Erdtagen, während sie die Sonne in etwa 225 Tagen umrundet. Außerdem dreht sie sich in die entgegengesetzte Richtung als die meisten Planeten.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P106": {"tekst": "Winzige Bärtierchen haben im offenen Weltall überlebt!", "wyjasnienie": "2007 brachte ein europäisches Experiment Bärtierchen an der Außenseite eines Satelliten an. Ein Teil überlebte Vakuum und starke Strahlung, und manche bekamen nach der Rückkehr zur Erde sogar Nachwuchs.", "zrodlo": "Prüfe: esa.int (ESA – Europäische Weltraumorganisation)"},
  "P110": {"tekst": "Koalas haben Fingerabdrücke, die von menschlichen kaum zu unterscheiden sind!", "wyjasnienie": "Die Fingerabdrücke von Koalas ähneln menschlichen so sehr, dass man sie selbst unter dem Mikroskop kaum unterscheiden kann. Sie haben sich unabhängig von Menschen und anderen Primaten entwickelt.", "zrodlo": "Prüfe: australian.museum (Australian Museum)"},
  "P113": {"tekst": "Die Zellen einer einzigen Frau werden in Laboren auf der ganzen Welt verwendet!", "wyjasnienie": "Zellen, die 1951 der krebskranken Amerikanerin Henrietta Lacks entnommen wurden, bildeten die Zelllinie HeLa. Diese Zellen vermehren sich im Labor immer weiter und halfen bei vielen medizinischen Studien, unter anderem zum Polio-Impfstoff.", "zrodlo": "Prüfe: hopkinsmedicine.org (Johns Hopkins Medicine)"},
  "P114": {"tekst": "Ein Banksy-Bild begann sich direkt nach der Versteigerung selbst zu zerstören!", "wyjasnienie": "2018, kurz nachdem „Girl with Balloon“ versteigert worden war, sprang ein im Rahmen versteckter Schredder an und zerschnitt das Werk teilweise. Es bekam später den Titel „Love Is in the Bin“ und wurde zu einem der bekanntesten Ereignisse der Gegenwartskunst.", "zrodlo": "Prüfe: sothebys.com (Auktionshaus Sotheby’s)"},
  "P117": {"tekst": "Bananen sind im botanischen Sinn Beeren, Erdbeeren aber nicht!", "wyjasnienie": "In der Botanik hängen die Namen von Früchten vom Aufbau der Blüte und von der Entstehung der Frucht ab. Die Banane erfüllt die Kriterien einer botanischen Beere, der rote, fleischige Teil der Erdbeere dagegen nicht.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P118": {"tekst": "Wombats machen würfelförmige Häufchen!", "wyjasnienie": "Wombat-Kot hat eine typische, fast würfelartige Form. Forschende erklärten, dass das unter anderem mit unterschiedlicher Elastizität der Darmwände zusammenhängt.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
  "P119": {"tekst": "Der Eiffelturm kann im Sommer ein bisschen wachsen!", "wyjasnienie": "Metall dehnt sich bei Wärme aus. An heißen Tagen kann der Eiffelturm ein paar Zentimeter höher werden, und wenn die Temperatur sinkt, zieht er sich wieder zusammen.", "zrodlo": "Prüfe: toureiffel.paris (offizielle Website des Eiffelturms)"},
  "P123": {"tekst": "Manche Schildkröten können unter Wasser Sauerstoff über die Kloake aufnehmen!", "wyjasnienie": "Einige Wasserschildkröten-Arten nutzen die Kloakenatmung, mit der sie einen Teil des Sauerstoffs aus dem Wasser aufnehmen. Nicht bei allen Arten ersetzt das aber die normale Lungenatmung.", "zrodlo": "Prüfe: australian.museum (Australian Museum)"},
  "P131": {"tekst": "In Island wurden zum ersten Mal in der Geschichte Mücken gefunden!", "wyjasnienie": "Lange war Island einer der wenigen Orte der Welt ohne Mücken. Im Oktober 2025 fing ein Naturfreund in seinem Garten im Tal Kjós drei Mücken der Art Culiseta annulata. Jetzt ist die Antarktis das einzige Land ohne Mücken.", "zrodlo": "Prüfe: national-geographic.pl (National Geographic Polen)"},
  "P133": {"tekst": "Forschende haben eine neue Farbe entdeckt, die du auf keinem Bildschirm sehen kannst!", "wyjasnienie": "Forschende der University of California, Berkeley reizten einzelne Zellen der Netzhaut mit einem Laser. Die Teilnehmenden sahen einen extrem gesättigten Blaugrünton, der „olo“ genannt wurde. Diese Farbe lässt sich auf keinem Bildschirm zeigen – man sieht sie nur im Labor. Die Studie erschien 2025 in „Science Advances“.", "zrodlo": "Prüfe: national-geographic.pl (National Geographic Polen)"},
  "P139": {"tekst": "Forschende haben Eis hergestellt, das so fest ist wie Beton!", "wyjasnienie": "Das stimmt. Die Forschenden verbanden Eis mit Zellulose aus Pflanzen. Das neue Material ist etwa 10-mal fester als normales Eis und könnte künftig als umweltfreundlicher, biologisch abbaubarer Baustoff dienen.", "zrodlo": "Prüfe: national-geographic.pl (National Geographic Polen)"},
  "P141": {"tekst": "Am Pol des Saturn bilden die Wolken ein Sechseck!", "wyjasnienie": "Das stimmt. Über dem Nordpol des Saturn wirbelt ein riesiges sechseckiges Wolkensystem mit einem gewaltigen Wirbel in der Mitte. Auch über dem Südpol wurde eine ungewöhnliche geometrische Struktur beobachtet.", "zrodlo": "Prüfe: national-geographic.pl (National Geographic Polen)"},
  "P143": {"tekst": "Pilze schicken sich nach Regen elektrische Signale!", "wyjasnienie": "Das stimmt. Japanische Forschende maßen elektrische Impulse zwischen Pilzen nach starkem Regen. Sie untersuchten den Zweifarbigen Lacktrichterling, der auch in polnischen Wäldern wächst.", "zrodlo": "Prüfe: national-geographic.pl (National Geographic Polen)"},
  "P151": {"tekst": "Haie sind älter als Bäume!", "wyjasnienie": "Die ältesten Haie tauchten vor etwa 450 Mio. Jahren auf, die ersten Bäume vor etwa 385 Mio. Jahren. Haie haben mehrere Massenaussterben überlebt.", "zrodlo": "Prüfe: nhm.ac.uk (Naturkundemuseum London)"},
  "P152": {"tekst": "Kleopatra lebte zeitlich näher an der Mondlandung als am Bau der Großen Pyramide!", "wyjasnienie": "Die Cheops-Pyramide wurde um 2560 v. Chr. gebaut, Kleopatra lebte im 1. Jahrhundert v. Chr. – über 2.400 Jahre später. Von Kleopatra bis zur Mondlandung 1969 vergingen etwa 2.000 Jahre.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P153": {"tekst": "Die Universität Oxford ist älter als das Aztekenreich!", "wyjasnienie": "In Oxford wurde schon Ende des 11. Jahrhunderts unterrichtet, die Aztekenhauptstadt Tenochtitlan wurde dagegen erst um 1325 gegründet.", "zrodlo": "Prüfe: ox.ac.uk (Universität Oxford)"},
  "P154": {"tekst": "Schnecken haben Tausende winzige Zähne!", "wyjasnienie": "Schnecken haben eine Raspelzunge (Radula) mit Reihen aus Tausenden winzigen Zähnchen, mit denen sie Nahrung abschaben. Abgenutzte Zähnchen werden ständig durch neue ersetzt.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P157": {"tekst": "Saturn könnte im Wasser schwimmen!", "wyjasnienie": "Saturn hat eine mittlere Dichte, die geringer ist als die von Wasser. Gäbe es eine so riesige Badewanne, würde der Planet an der Oberfläche treiben.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "P167": {"tekst": "Auf der Erde leben etwa 20 Billiarden Ameisen!", "wyjasnienie": "2022 schätzten Forschende, dass auf der Erde etwa 20 Billiarden (20.000.000.000.000.000) Ameisen leben. Ihre Gesamtmasse ist größer als die aller wild lebenden Vögel und Säugetiere zusammen.", "zrodlo": "Prüfe: pnas.org (Fachzeitschrift PNAS)"},
  "P174": {"tekst": "Es gibt eine Qualle, die sich „verjüngen“ kann!", "wyjasnienie": "Die Qualle Turritopsis dohrnii kann unter schwierigen Bedingungen in ein früheres Entwicklungsstadium zurückkehren und ihr Leben neu beginnen. Man nennt sie manchmal die „unsterbliche Qualle“.", "zrodlo": "Prüfe: amnh.org (Amerikanisches Naturkundemuseum)"},
  "P175": {"tekst": "Einer der größten Organismen der Erde ist ein Wald, der ein einziger Baum ist!", "wyjasnienie": "Pando in Utah ist ein Wald aus Zitterpappeln, die aus einem einzigen Wurzelsystem wachsen und dieselben Gene haben. Er bedeckt etwa 43 Hektar.", "zrodlo": "Prüfe: fs.usda.gov (Forstbehörde der USA)"},
  "P191": {"tekst": "Die erste SMS wurde 1992 verschickt und lautete „Merry Christmas“!", "wyjasnienie": "Die Nachricht schickte der Ingenieur Neil Papworth in Großbritannien von einem Computer an ein Handy. Damals konnte man auf Handys noch keine SMS schreiben.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "P196": {"tekst": "Auf der Erde gibt es mehr Bäume als Sterne in der Milchstraße!", "wyjasnienie": "Eine Studie von 2015 schätzte die Zahl der Bäume auf der Erde auf etwa 3 Billionen. Die Milchstraße hat etwa 100–400 Milliarden Sterne.", "zrodlo": "Prüfe: nature.com (Fachzeitschrift Nature)"},
  "F1": {"tekst": "Der Blitz schlägt nie zweimal an derselben Stelle ein!", "wyjasnienie": "Im Netz heißt es oft, eine solche Stelle sei danach „sicher“. Tatsächlich werden hohe Objekte wie Wolkenkratzer und Masten viele Male getroffen, sogar mehrmals während eines Gewitters.", "zrodlo": "Prüfe: weather.gov (Nationaler Wetterdienst der USA)"},
  "F3": {"tekst": "Die Chinesische Mauer ist vom Weltall aus mit bloßem Auge sichtbar!", "wyjasnienie": "Diese Behauptung stand in Schulbüchern und im Netz. Die Mauer ist sehr lang, aber schmal und hat eine ähnliche Farbe wie ihre Umgebung, deshalb können Astronauten sie aus der Umlaufbahn ohne Kamera praktisch nicht sehen.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "F6": {"tekst": "Die Zunge hat eigene Zonen für süß, salzig, sauer und bitter!", "wyjasnienie": "Die „Zungenkarte“ taucht in vielen Schulbüchern und Grafiken im Netz auf. In Wahrheit sitzen Rezeptoren für alle Geschmacksrichtungen auf der ganzen Zunge, auch wenn ihre Empfindlichkeit leicht unterschiedlich sein kann.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F11": {"tekst": "Einstein ist in Mathe durchgefallen, bevor er ein berühmter Wissenschaftler wurde!", "wyjasnienie": "Im Netz wird oft erzählt, Albert Einstein habe in der Schule Probleme mit Mathe gehabt. Die Geschichte soll zeigen, dass selbst Schulversagen ein Zeichen für ein künftiges Genie sein kann. In Wahrheit war Einstein schon als Jugendlicher gut in Mathe.", "zrodlo": "Prüfe: library.ethz.ch (Bibliothek der ETH Zürich)"},
  "F13": {"tekst": "Goldfische vergessen nach drei Sekunden alles!", "wyjasnienie": "Im Netz liest man, Goldfische hätten ein so kurzes Gedächtnis, dass sie sich nicht einmal ihre Umgebung merken können. Studien zeigen aber, dass Fische lernen, sich Dinge merken und bestimmte Reize verknüpfen können.", "zrodlo": "Prüfe: livescience.com (Live Science)"},
  "F30": {"tekst": "Ein Wolf griff in der Toskana einen Zweijährigen an – der Familienhund rettete ihn!", "wyjasnienie": "Auf Facebook kursierten Beiträge über einen Hund, der ein zweijähriges Kind in Italien vor einem Wolfsangriff verteidigt haben soll. Die rührende Geschichte vom Heldenhund verbreitete sich schnell und wurde von einigen Medien übernommen. Tatsächlich verteidigte der Hund die Familie, aber laut den toskanischen Behörden griff der Wolf das Kind nicht an – ein Teil der Wahrheit wurde zur Sensation verdreht.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F35": {"tekst": "Ein Bauer in Frankreich weint, weil die Polizei ihm seine Kühe weggenommen hat!", "wyjasnienie": "Auf Facebook wurde ein Video eines verzweifelten französischen Bauern geteilt, dem Polizisten die Kühe wegnehmen. Viele glaubten das Video und hatten in den Kommentaren Mitleid mit dem Bauern. In Wahrheit hat eine KI das Video erzeugt, und das Konto, das es veröffentlichte, lädt nur KI-Inhalte hoch.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F47": {"tekst": "Forschende haben den ausgestorbenen Schattenwolf wiederbelebt!", "wyjasnienie": "Das ist Manipulation. Ein Biotech-Unternehmen züchtete Grauwölfe mit veränderten Genen, damit sie dem ausgestorbenen Schattenwolf ähneln. Es ist aber nicht dieselbe Art, und die reißerischen Schlagzeilen ließen dieses Detail weg.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F49": {"tekst": "Dieses Video zeigt eine Maus, die wirklich ins All geflogen ist!", "wyjasnienie": "Falsch. Das Video, das in sozialen Medien kursiert, wurde bearbeitet und beweist nichts. Bevor du einem Video glaubst, prüf, ob seriöse Quellen darüber berichtet haben.", "zrodlo": "Prüfe: demagog.org.pl (Demagog – polnisches Faktencheck-Portal)"},
  "F51": {"tekst": "Chamäleons wechseln die Farbe, um sich der Umgebung anzupassen!", "wyjasnienie": "Im Netz sieht man oft Chamäleons, die vor jedem Hintergrund „verschwinden“. Tatsächlich dient der Farbwechsel vor allem der Verständigung mit anderen Chamäleons und der Temperaturregelung, nicht der Tarnung auf Kommando.", "zrodlo": "Prüfe: nationalgeographic.com (National Geographic)"},
  "F53": {"tekst": "Ein Hundejahr entspricht immer 7 Menschenjahren!", "wyjasnienie": "Diese einfache Umrechnung gibt es seit Jahrzehnten. Hunde altern in den ersten zwei Lebensjahren am schnellsten, danach langsamer, und es hängt auch von Größe und Rasse ab. Mal 7 ist eine starke Vereinfachung.", "zrodlo": "Prüfe: avma.org (Amerikanischer Tierärzteverband)"},
  "F56": {"tekst": "Wer Karotten isst, kann im Dunkeln sehen!", "wyjasnienie": "Den Mythos verbreitete britische Propaganda im Zweiten Weltkrieg, um zu verschleiern, dass Piloten Radar nutzten. Karotten enthalten Vitamin A, das wichtig für die Augen ist, verleihen aber keine „Nachtsicht“.", "zrodlo": "Prüfe: smithsonianmag.com (Smithsonian Magazine)"},
  "F58": {"tekst": "Napoleon war außergewöhnlich klein!", "wyjasnienie": "Napoleon war etwa 168–170 cm groß, also durchschnittlich für seine Zeit. Der Mythos entstand unter anderem durch Unterschiede zwischen französischen und englischen Maßeinheiten und durch britische Karikaturen.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F59": {"tekst": "Im Mittelalter glaubten alle, die Erde sei flach!", "wyjasnienie": "Dieser Mythos wird in vielen Videos wiederholt. Gebildete Menschen wussten im Mittelalter, dass die Erde eine Kugel ist – dieses Wissen stammte von den alten Griechen.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F61": {"tekst": "Auf der Südhalbkugel dreht sich das Wasser im Waschbecken andersherum!", "wyjasnienie": "Touristen am Äquator sehen sich Vorführungen mit Wassertrichtern an. Die Corioliskraft ist zu schwach, um Wasser im Waschbecken zu beeinflussen – die Drehrichtung hängt von der Form des Beckens und der Wasserbewegung ab.", "zrodlo": "Prüfe: noaa.gov (NOAA – US-Behörde für Ozeane und Atmosphäre)"},
  "F62": {"tekst": "Nach dem Tod wachsen Haare und Nägel weiter!", "wyjasnienie": "Das ist ein beliebtes Horrorfilm-Motiv. Tatsächlich trocknet die Haut nach dem Tod aus und zieht sich zusammen, sodass Haare und Nägel länger wirken. Zum Wachsen braucht es lebende Zellen.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
  "F63": {"tekst": "Menschen sind entweder „Linkshirnler“ (logisch) oder „Rechtshirnler“ (kreativ)!", "wyjasnienie": "Persönlichkeitstests im Netz ordnen Menschen einer Gehirnhälfte zu. Beide Hälften arbeiten eng zusammen, und Studien haben nicht bestätigt, dass Menschen eine „dominante“ Hälfte haben, die ihren Charakter bestimmt.", "zrodlo": "Prüfe: brainfacts.org (BrainFacts – Society for Neuroscience)"},
  "F64": {"tekst": "Lemminge begehen Massenselbstmord, indem sie von Klippen springen!", "wyjasnienie": "Den Mythos festigte ein Naturfilm von 1958, in dem das Filmteam die Szenen inszeniert hatte. Lemminge wandern, wenn es sehr viele von ihnen gibt, und können dabei zufällig sterben, tun das aber nicht absichtlich.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F70": {"tekst": "Im Sommer ist es warm, weil die Erde dann näher an der Sonne ist!", "wyjasnienie": "Das ist ein häufiger Irrtum. Die Jahreszeiten entstehen durch die Neigung der Erdachse. Am nächsten an der Sonne ist die Erde Anfang Januar – also mitten im Winter auf der Nordhalbkugel.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "F71": {"tekst": "Die dunkle Seite des Mondes liegt immer im Dunkeln!", "wyjasnienie": "Der Name lässt vermuten, dass dort nie die Sonne scheint. Tatsächlich ist die „Rückseite“ nur ständig von der Erde abgewandt, wird aber genauso von der Sonne beleuchtet wie die sichtbare Seite.", "zrodlo": "Prüfe: science.nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "F72": {"tekst": "Der Polarstern ist der hellste Stern am Himmel!", "wyjasnienie": "Viele denken das, weil er für die Navigation wichtig ist. Der hellste Stern am Nachthimmel ist Sirius. Der Polarstern ist dafür bekannt, dass er den Norden anzeigt, nicht für seine Helligkeit.", "zrodlo": "Prüfe: esa.int (ESA – Europäische Weltraumorganisation)"},
  "F73": {"tekst": "Astronauten schweben auf der ISS, weil es im Weltall keine Schwerkraft gibt!", "wyjasnienie": "In der Höhe der Station ist die Schwerkraft fast so stark wie auf der Erde. Astronauten schweben, weil die Station mit ihnen ständig im freien Fall um die Erde ist.", "zrodlo": "Prüfe: nasa.gov (NASA – US-Raumfahrtbehörde)"},
  "F74": {"tekst": "Diamanten entstehen aus zusammengepresster Steinkohle!", "wyjasnienie": "Das behaupten viele Filme und Zeichentrickserien. Die meisten Diamanten entstanden aus reinem Kohlenstoff tief im Erdmantel, viel tiefer als Steinkohlelager, und sind oft älter als diese.", "zrodlo": "Prüfe: britannica.com (Encyclopaedia Britannica)"},
  "F79": {"tekst": "Glas ist eine Flüssigkeit, die sehr langsam fließt – deshalb sind alte Fensterscheiben unten dicker!", "wyjasnienie": "Dieser Mythos taucht oft bei historischen Fenstern auf. Bei Raumtemperatur fließt Glas nicht merklich. Alte Scheiben waren wegen des früheren Herstellungsverfahrens ungleichmäßig und wurden oft mit der dickeren Seite nach unten eingebaut.", "zrodlo": "Prüfe: scientificamerican.com (Scientific American)"},
};
